"""
Detection Rules Engine
Task 03 - EdVyro Cybersecurity Internship

Defines defensible, production-grade detection logic for:
1. Targeted Brute Force (Vertical Password Guessing - MITRE T1110.001)
2. Password Spraying (Horizontal Password Guessing - MITRE T1110.003)
3. Unusual Access / Post-Attack Activity Anomaly (MITRE T1078)
"""

from typing import List, Dict, Any, Optional
from datetime import datetime, timezone


class SecurityAlert:
    """Represents a structured detection alert generated by SIEM rules."""
    def __init__(
        self,
        rule_id: str,
        rule_name: str,
        severity: str,
        mitre_technique: str,
        start_time: str,
        end_time: str,
        target_accounts: List[str],
        source_ips: List[str],
        description: str,
        evidence: List[Dict[str, Any]],
        assumptions: List[str],
        recommended_action: str
    ):
        self.rule_id = rule_id
        self.rule_name = rule_name
        self.severity = severity
        self.mitre_technique = mitre_technique
        self.start_time = start_time
        self.end_time = end_time
        self.target_accounts = target_accounts
        self.source_ips = source_ips
        self.description = description
        self.evidence = evidence
        self.assumptions = assumptions
        self.recommended_action = recommended_action

    def to_dict(self) -> Dict[str, Any]:
        return {
            "rule_id": self.rule_id,
            "rule_name": self.rule_name,
            "severity": self.severity,
            "mitre_technique": self.mitre_technique,
            "start_time": self.start_time,
            "end_time": self.end_time,
            "target_accounts": self.target_accounts,
            "source_ips": self.source_ips,
            "description": self.description,
            "evidence_count": len(self.evidence),
            "assumptions": self.assumptions,
            "recommended_action": self.recommended_action
        }


class DetectionEngine:
    """Evaluates normalized authentication logs against defensible detection rules."""

    def __init__(
        self,
        brute_force_threshold: int = 3,
        brute_force_window_seconds: int = 120,
        spray_threshold: int = 3,
        spray_window_seconds: int = 300,
        unusual_access_window_seconds: int = 14400  # 4 hours
    ):
        self.brute_force_threshold = brute_force_threshold
        self.brute_force_window_seconds = brute_force_window_seconds
        self.spray_threshold = spray_threshold
        self.spray_window_seconds = spray_window_seconds
        self.unusual_access_window_seconds = unusual_access_window_seconds

    def parse_time(self, ts_str: str) -> datetime:
        return datetime.fromisoformat(ts_str.replace("Z", "+00:00"))

    def detect_targeted_brute_force(self, records: List[Dict[str, Any]]) -> List[SecurityAlert]:
        """
        Rule 1: Targeted Brute Force (Vertical Guessing)
        Identifies >= N failed login attempts against a single user account
        within a sliding time window.
        """
        alerts = []
        user_failures: Dict[str, List[Dict[str, Any]]] = {}

        # Collect all failed logins grouped by user
        for r in records:
            if r.get("event_raw") == "password_login" and r.get("result_normalized") == "FAILURE":
                uid = r["user_id"]
                if uid not in user_failures:
                    user_failures[uid] = []
                user_failures[uid].append(r)

        # Evaluate sliding window per user
        for uid, fails in user_failures.items():
            fails.sort(key=lambda x: self.parse_time(x["timestamp_iso"]))
            for i in range(len(fails)):
                window = [fails[i]]
                start_dt = self.parse_time(fails[i]["timestamp_iso"])
                for j in range(i + 1, len(fails)):
                    curr_dt = self.parse_time(fails[j]["timestamp_iso"])
                    if (curr_dt - start_dt).total_seconds() <= self.brute_force_window_seconds:
                        window.append(fails[j])
                    else:
                        break

                if len(window) >= self.brute_force_threshold:
                    ips = list(set(x["source_ip"] for x in window))
                    devices = list(set(x.get("device_raw", "unknown") for x in window))
                    alert = SecurityAlert(
                        rule_id="RULE-01-BRUTE-FORCE",
                        rule_name="Targeted Vertical Brute-Force Password Guessing",
                        severity="HIGH",
                        mitre_technique="T1110.001 - Password Guessing",
                        start_time=window[0]["timestamp_iso"],
                        end_time=window[-1]["timestamp_iso"],
                        target_accounts=[uid],
                        source_ips=ips,
                        description=(
                            f"Account '{uid}' experienced {len(window)} rapid failed login attempts "
                            f"from IP(s) {ips} within "
                            f"{int((self.parse_time(window[-1]['timestamp_iso']) - start_dt).total_seconds())}s. "
                            f"Reported client devices: {devices}."
                        ),
                        evidence=window,
                        assumptions=[
                            "Rapid consecutive failures suggest automated or repeated guessing rather than typical typos.",
                            "Account lockout mechanism successfully engaged following the 3rd attempt."
                        ],
                        recommended_action=(
                            "Verify account lock status; notify student user; review auth logs for post-lock attempts; "
                            "inspect whether IP belongs to legitimate user or compromised endpoint."
                        )
                    )
                    alerts.append(alert)
                    break  # Avoid duplicate sub-window alerts for same cluster

        return alerts

    def detect_password_spraying(self, records: List[Dict[str, Any]]) -> List[SecurityAlert]:
        """
        Rule 2: Password Spraying (Horizontal Guessing)
        Identifies a single source IP targeting >= N distinct user accounts
        with failed logins within a sliding time window.
        """
        alerts = []
        ip_failures: Dict[str, List[Dict[str, Any]]] = {}

        for r in records:
            if r.get("event_raw") == "password_login" and r.get("result_normalized") == "FAILURE":
                ip = r["source_ip"]
                if ip not in ip_failures:
                    ip_failures[ip] = []
                ip_failures[ip].append(r)

        for ip, fails in ip_failures.items():
            fails.sort(key=lambda x: self.parse_time(x["timestamp_iso"]))
            for i in range(len(fails)):
                window = [fails[i]]
                start_dt = self.parse_time(fails[i]["timestamp_iso"])
                for j in range(i + 1, len(fails)):
                    curr_dt = self.parse_time(fails[j]["timestamp_iso"])
                    if (curr_dt - start_dt).total_seconds() <= self.spray_window_seconds:
                        window.append(fails[j])
                    else:
                        break

                distinct_users = list(set(x["user_id"] for x in window))
                if len(distinct_users) >= self.spray_threshold:
                    devices = list(set(x.get("device_raw", "unknown") for x in window))
                    duration_s = int((self.parse_time(window[-1]["timestamp_iso"]) - start_dt).total_seconds())
                    alert = SecurityAlert(
                        rule_id="RULE-02-PASSWORD-SPRAY",
                        rule_name="Horizontal Password Spraying Attack",
                        severity="CRITICAL",
                        mitre_technique="T1110.003 - Password Spraying",
                        start_time=window[0]["timestamp_iso"],
                        end_time=window[-1]["timestamp_iso"],
                        target_accounts=distinct_users,
                        source_ips=[ip],
                        description=(
                            f"Source IP '{ip}' targeted {len(distinct_users)} distinct accounts "
                            f"({', '.join(distinct_users)}) with failed logins within {duration_s}s. "
                            f"All attempts reported anomalous device header '{devices[0]}'."
                        ),
                        evidence=window,
                        assumptions=[
                            "Attempts targeting multiple distinct user accounts in rapid succession "
                            "demonstrate horizontal password spraying intended to bypass per-account lockout.",
                            "The 'unknown' device header strongly indicates scripted tooling (e.g., Hydra, Curl, Python-requests)."
                        ],
                        recommended_action=(
                            "Enforce immediate edge IP blocking on source IP; evaluate all sprayed user accounts for subsequent successful logins; "
                            "trigger forced password reset and MFA verification for targeted accounts."
                        )
                    )
                    alerts.append(alert)
                    break

        return alerts

    def detect_unusual_access(self, records: List[Dict[str, Any]], spray_alerts: List[SecurityAlert]) -> List[SecurityAlert]:
        """
        Rule 3: Unusual Access / Post-Attack Activity Anomaly
        Detects successful logins for accounts previously targeted in password spray
        or brute-force attacks within the lookback window, especially with distinct IP/device.
        """
        alerts = []
        # Extract all users targeted in spraying or brute force
        targeted_users = set()
        for alert in spray_alerts:
            targeted_users.update(alert.target_accounts)

        # Scan for successful logins by targeted users occurring AFTER the attack
        for r in records:
            if (
                r.get("event_raw") == "password_login"
                and r.get("result_normalized") == "SUCCESS"
                and r["user_id"] in targeted_users
            ):
                uid = r["user_id"]
                success_dt = self.parse_time(r["timestamp_iso"])

                # Find the preceding attack event for this user
                prior_attacks = [
                    x for x in records
                    if x["user_id"] == uid
                    and x.get("result_normalized") == "FAILURE"
                    and self.parse_time(x["timestamp_iso"]) < success_dt
                ]

                if prior_attacks:
                    last_attack = prior_attacks[-1]
                    last_attack_dt = self.parse_time(last_attack["timestamp_iso"])
                    elapsed_s = int((success_dt - last_attack_dt).total_seconds())

                    if elapsed_s <= self.unusual_access_window_seconds:
                        alert = SecurityAlert(
                            rule_id="RULE-03-UNUSUAL-ACCESS",
                            rule_name="Unusual Access Post-Attack Anomaly",
                            severity="HIGH",
                            mitre_technique="T1078 - Valid Accounts",
                            start_time=last_attack["timestamp_iso"],
                            end_time=r["timestamp_iso"],
                            target_accounts=[uid],
                            source_ips=[last_attack["source_ip"], r["source_ip"]],
                            description=(
                                f"Account '{uid}' was targeted during a password spray at "
                                f"{last_attack['timestamp_iso']} from {last_attack['source_ip']} (device: {last_attack.get('device_raw')}), "
                                f"and subsequently achieved a successful login at {r['timestamp_iso']} "
                                f"from {r['source_ip']} ({r.get('network_zone', 'Unknown')}) using device '{r.get('device_raw')}'. "
                                f"Time delta: {elapsed_s // 60} minutes."
                            ),
                            evidence=[last_attack, r],
                            assumptions=[
                                "HYPOTHESIS A (Benign): The legitimate student logged in normally from campus network via their personal iPhone.",
                                "HYPOTHESIS B (Compromised): The attacker acquired credentials through out-of-band means or used an internal campus proxy.",
                                "CONCLUSION: Defensible investigation requires treating this as suspicious until out-of-band user verification is completed."
                            ],
                            recommended_action=(
                                "Contact student user out-of-band to confirm authentication from iOS device at 11:47:09Z; "
                                "check device fingerprint and MAC address on campus Wi-Fi DHCP logs; "
                                "inspect subsequent user session telemetry for anomalous portal activity."
                            )
                        )
                        alerts.append(alert)

        return alerts

    def run_all_detections(self, records: List[Dict[str, Any]]) -> List[SecurityAlert]:
        """Runs the entire detection ruleset against normalized records."""
        all_alerts = []
        bf_alerts = self.detect_targeted_brute_force(records)
        all_alerts.extend(bf_alerts)

        spray_alerts = self.detect_password_spraying(records)
        all_alerts.extend(spray_alerts)

        anomaly_alerts = self.detect_unusual_access(records, spray_alerts)
        all_alerts.extend(anomaly_alerts)

        return all_alerts


if __name__ == "__main__":
    import os
    from normalizer import normalize_log_file

    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    in_path = os.path.join(base_dir, "data", "raw_authentication_log.csv")
    recs = normalize_log_file(in_path)

    engine = DetectionEngine()
    alerts = engine.run_all_detections(recs)

    print(f"\n[+] Detection Engine executed. Generated {len(alerts)} alerts:\n")
    for a in alerts:
        print(f"[{a.severity}] {a.rule_id} - {a.rule_name}")
        print(f"    Target Accounts : {a.target_accounts}")
        print(f"    Source IPs      : {a.source_ips}")
        print(f"    Timespan        : {a.start_time} -> {a.end_time}")
        print(f"    Description     : {a.description}\n")
